<script setup lang="ts">
import { computed, onUnmounted, ref, shallowRef, watch } from 'vue'
import { onBeforeRouteLeave, onBeforeRouteUpdate, useRoute } from 'vue-router'
import { ElMessageBox } from 'element-plus'
import { parseRuntimeUtc } from '../utils/runtimeConfigurationInput'
import { api, isCancelled } from '../api/client'
import type { Configuration, ConfigurationRevision } from '../api/types'
import { can, session, switchingTenant, contextGeneration } from '../stores/session'
import { contextTransitionGuards } from '../utils/contextTransitionGuard'
import { createRuntimeConfigurationWorkspace, emptyRuntimeState, type RuntimeState, type RuntimeDefinition, type RuntimeRelease } from '../utils/runtimeConfigurationWorkspace'
import { readConfigurationRevision } from '../utils/configurationRevisionWriter'
import { displayTime } from '../utils/display'
import ConfigurationRevisions from '../components/ConfigurationRevisions.vue'
import ProductionReadinessPanel from '../components/ProductionReadinessPanel.vue'
import ApiErrorNotice from '../components/ApiErrorNotice.vue'
import baseline from '../../../../contracts/config-baseline.json'
import {runtimeConsumer} from '../utils/runtimeConsumers'
const expectedKeys=new Set(baseline.settings.map(item=>item.key))
const completeKeys=(items:unknown):items is {key:string}[]=>Array.isArray(items)&&items.length===expectedKeys.size&&new Set(items.map(item=>item?.key)).size===expectedKeys.size&&items.every(item=>item&&typeof item.key==='string'&&expectedKeys.has(item.key))
const route=useRoute()
const state=shallowRef<RuntimeState>(emptyRuntimeState()),workspace=createRuntimeConfigurationWorkspace(api,s=>{state.value=s})
const definitions=ref<RuntimeDefinition[]>([]),registry=ref<Configuration[]>([]),catalogBusy=ref(false),catalogError=ref<unknown>(null),query=ref(''),question=ref(''),editableOnly=ref(false)
const revisions=ref<ConfigurationRevision[]>([]),revisionError=ref<unknown>(null),revisionsOpen=ref(false),selectedRevision=ref(''),chosenRollback=ref<RuntimeRelease|null>(null)
const activation=ref<'IMMEDIATE'|'SCHEDULED'>('IMMEDIATE'),effectiveAt=ref(''),expiresAt=ref(''),reason=ref(''),ack=ref(false),validation=ref(''),validated=ref(false)
const permitted=computed(()=>session.value?.mode==='remote_test'&&session.value.user.role==='padmin'&&can('configurations:read')&&!switchingTenant.value)
const writable=computed(()=>permitted.value&&can('configurations:write'))
const selected=computed(()=>definitions.value.find(d=>d.key===state.value.key)??null)
const selectedRegistry=computed(()=>registry.value.find(d=>d.key===state.value.key)??null)
const approved=computed(()=>revisions.value.filter(r=>r.workflow_status==='APPROVED'))
const candidate=computed(()=>approved.value.find(r=>r.id===selectedRevision.value)??null)
const visible=computed(()=>definitions.value.filter(d=>(!editableOnly.value||d.editable)&&(!question.value||d.question_ids.includes(question.value))&&`${d.key} ${d.description} ${d.source}`.toLocaleLowerCase().includes(query.value.trim().toLocaleLowerCase())))
const prepared=ref<{key:string;version:number;definitionHash:string}|null>(null),confirming=ref(false),validating=ref(false)
const dirty=computed(()=>state.value.attempt?.state!=='accepted'&&Boolean(selectedRevision.value||chosenRollback.value||activation.value!=='IMMEDIATE'||effectiveAt.value||expiresAt.value||reason.value||ack.value))
const locked=computed(()=>Boolean(state.value.busy)||Boolean(state.value.attempt)||!writable.value||!prepared.value||confirming.value||validating.value)
const statuses:Record<string,string>={UNCONFIGURED:'尚未发布',SCHEDULED:'等待计划生效',ACTIVE:'测试配置生效中',DISABLED:'已明确禁用',EXPIRED:'已到期',DEFINITION_CHANGED:'定义已变更，须重新校验发布'}
let epoch=0,abort:AbortController|null=null,disposed=false,validationEpoch=0,validationAbort:AbortController|null=null
function cancelValidation(){++validationEpoch;validationAbort?.abort();validationAbort=null;validating.value=false;validated.value=false}
function clearForm(){cancelValidation();prepared.value=null;selectedRevision.value='';chosenRollback.value=null;activation.value='IMMEDIATE';effectiveAt.value='';expiresAt.value='';reason.value='';ack.value=false;validation.value='';validated.value=false}
async function catalog(){if(!permitted.value)return;const turn=++epoch;abort?.abort();abort=new AbortController();catalogBusy.value=true;catalogError.value=null;definitions.value=[];registry.value=[];try{const [d,r]=await Promise.all([api.request<{items:RuntimeDefinition[];question_count:number;source:string}>('/runtime-configurations/catalog',{signal:abort.signal}),api.request<{items:Configuration[]}>('/configurations',{signal:abort.signal})]);if(turn!==epoch||disposed)return;if(d.question_count!==31||d.source!=='code_catalog'||!completeKeys(d.items)||!completeKeys(r.items))throw Error('配置目录不完整，未显示替代条目');definitions.value=d.items;registry.value=r.items;validated.value=false;ack.value=false;const target=route.query.key;if(typeof target==='string'&&target!==state.value.key&&d.items.some(item=>item.key===target))void select(target);else if(state.value.key)void refresh()}catch(e){if(turn===epoch&&!isCancelled(e))catalogError.value=e}finally{if(turn===epoch)catalogBusy.value=false}}
async function readProposals(key:string){const turn=epoch;revisionError.value=null;revisions.value=[];try{const result=await api.request<{items:unknown[]}>('/configurations/'+key+'/revisions');if(disposed||turn!==epoch||state.value.key!==key)return;const s=session.value!;revisions.value=result.items.map(r=>readConfigurationRevision(r,{tenantId:s.tenant.id,actorId:s.user.id,permissionVersion:s.permission_version,configurationKey:key}))}catch(e){if(!disposed&&turn===epoch&&state.value.key===key&&!isCancelled(e))revisionError.value=e}}
async function discard(){
 if(workspace.unresolved()){validation.value='发布结果尚未确认，请保留当前页面并重试原请求';return false}
 if(confirming.value)return false
 if(!dirty.value)return true
 const turn=epoch;confirming.value=true
 try{await ElMessageBox.confirm('继续将丢弃本页未保存的配置发布编辑；已保存的服务器记录不会删除。','离开配置编辑',{confirmButtonText:'丢弃并继续',cancelButtonText:'保留编辑',type:'warning'});return !disposed&&turn===epoch&&!workspace.unresolved()}
 catch{return false}finally{if(!disposed&&turn===epoch)confirming.value=false}
}
async function select(key:string){if(workspace.unresolved()||state.value.busy){validation.value='请先核对当前发布的原请求结果';return}if(key===state.value.key)return;const turn=epoch;if(!await discard()||disposed||turn!==epoch)return;workspace.clearAttempt();clearForm();if(await workspace.load(key))void readProposals(key)}
async function prepare(){if(!writable.value||state.value.busy||workspace.unresolved()||!state.value.current||!selected.value?.editable)return false;const turn=epoch,key=state.value.key,version=state.value.current.latest_version,definitionHash=selected.value.definition_hash;if(!await discard()||disposed||turn!==epoch||key!==state.value.key||version!==state.value.current?.latest_version)return false;if(!workspace.clearAttempt())return false;clearForm();prepared.value={key,version,definitionHash};return true}

async function refresh(){if(workspace.unresolved()){validation.value='普通刷新不能确认丢失的发布回执，请重试原请求';return}if(await workspace.load())void readProposals(state.value.key)}
async function changed(){if(await workspace.load())void readProposals(state.value.key)}
watch(selectedRevision,()=>{cancelValidation();if(selectedRevision.value)chosenRollback.value=null;ack.value=false},{flush:'sync'})
watch([activation,effectiveAt,expiresAt,reason,()=>state.value.current?.latest_version],()=>{ack.value=false})
async function validateCandidate(){
 if(!candidate.value||locked.value)return
 const key=state.value.key,id=candidate.value.id,turn=epoch,token=++validationEpoch,controller=new AbortController();validationAbort=controller;validation.value='';validating.value=true;validated.value=false
 try{const r=await api.request<{valid:boolean;configuration_key:string;definition_hash:string;saved:boolean}>('/runtime-configurations/'+key+'/validate',{method:'POST',body:{value:candidate.value.proposed_value},signal:controller.signal});if(!disposed&&turn===epoch&&token===validationEpoch&&state.value.key===key&&candidate.value?.id===id){if(r.valid!==true||r.configuration_key!==key||r.definition_hash!==prepared.value?.definitionHash||r.saved!==false)throw Error('校验返回与当前配置不一致');validated.value=true}}
 catch(e){if(!disposed&&turn===epoch&&token===validationEpoch&&!isCancelled(e))validation.value=e instanceof Error?e.message:'校验未完成'}
 finally{if(!disposed&&turn===epoch&&token===validationEpoch){validating.value=false;validationAbort=null}}
}

async function publish(action:'PUBLISH'|'ROLLBACK'|'DISABLE'){
 if(locked.value||!ack.value||!selected.value?.editable||!state.value.current)return
 const turn=epoch;validation.value='';try{if(!prepared.value||prepared.value.key!==state.value.key||prepared.value.version!==state.value.current.latest_version||prepared.value.definitionHash!==selected.value.definition_hash)throw Error('配置版本或定义已变化，请重新准备本次发布并核对输入');if(action==='PUBLISH'&&(!candidate.value||!validated.value))throw Error('请明确选择并校验已审核提案');if(action==='ROLLBACK'&&!chosenRollback.value)throw Error('请选择历史版本');if(!reason.value.trim())throw Error('请填写本次发布、回滚或禁用原因');if(action==='DISABLE'&&expiresAt.value)throw Error('禁用不设置到期时间；要恢复需显式发布新版本');const effective=activation.value==='IMMEDIATE'?null:parseRuntimeUtc(effectiveAt.value),expires=parseRuntimeUtc(expiresAt.value,true);const okay=await workspace.publish({expected_version:prepared.value.version,expected_definition_hash:prepared.value.definitionHash,action,revision_id:action==='PUBLISH'?candidate.value!.id:null,revision_version:action==='PUBLISH'?candidate.value!.version:null,target_release_id:action==='ROLLBACK'?chosenRollback.value!.id:null,activation:activation.value,effective_at:effective,expires_at:expires,reason:reason.value.trim()});if(okay&&!disposed&&turn===epoch){ack.value=false;await workspace.load()}}catch(e){if(!disposed&&turn===epoch)validation.value=e instanceof Error?e.message:'请求未发送'}
}
async function retry(){const turn=epoch;if(await workspace.retry()&&!disposed&&turn===epoch){ack.value=false;await workspace.load()}}
async function prepareRollback(row:RuntimeRelease){if(locked.value||row.action==='DISABLE')return;const turn=epoch;if(!await discard()||disposed||turn!==epoch)return;const basis={...prepared.value!};clearForm();prepared.value=basis;chosenRollback.value=row}
async function newCommand(){const turn=epoch;if(await discard()&&!disposed&&turn===epoch&&workspace.clearAttempt()){clearForm();void refresh()}}
async function leave(){return discard()}
onBeforeRouteLeave(leave);onBeforeRouteUpdate(async()=>{if(state.value.busy||!await leave())return false;clearForm();return true});watch(()=>route.query.key,value=>{if(typeof value==='string'&&definitions.value.some(d=>d.key===value))void select(value)});const unregister=contextTransitionGuards.register(async()=>leave())
function beforeUnload(e:BeforeUnloadEvent){if(workspace.unresolved()||dirty.value){e.preventDefault();e.returnValue=''}}
window.addEventListener('beforeunload',beforeUnload)
const authorizationKey=computed(()=>JSON.stringify([contextGeneration.value,session.value?.tenant.id,session.value?.user.id,session.value?.permission_version,session.value?.account_version,session.value?.user.role,[...(session.value?.capabilities??[])].sort(),permitted.value,writable.value]))
watch(authorizationKey,()=>{++epoch;confirming.value=false;abort?.abort();definitions.value=[];registry.value=[];revisions.value=[];revisionsOpen.value=false;clearForm();const s=session.value;workspace.reset(s&&permitted.value?{tenantId:s.tenant.id,actorId:s.user.id,permissionVersion:s.permission_version}:null);if(permitted.value)void catalog()},{immediate:true,flush:'sync'})
onUnmounted(()=>{disposed=true;++epoch;cancelValidation();abort?.abort();workspace.dispose();unregister();window.removeEventListener('beforeunload',beforeUnload)})
</script>
<template>
 <section class="runtime-config-page">
  <h1 class="page-title-sr">运行配置与发布</h1>
  
  <p v-if="!permitted">当前没有配置读取权限。</p>
  <template v-else>
   <ProductionReadinessPanel />
   <ApiErrorNotice :error="catalogError" :retrying="catalogBusy" @retry="catalog" />
   <div class="runtime-layout"><aside class="runtime-catalog panel"><div class="runtime-heading content-toolbar"><h2>配置目录</h2><button :disabled="catalogBusy||Boolean(state.busy)||workspace.unresolved()" @click="catalog">刷新目录</button><div class="content-actions"><router-link to="/configurations">配置登记与历史提案</router-link></div></div><label>搜索配置<input v-model="query" type="search" aria-label="搜索运行配置" placeholder="配置键 / 说明 / 合同来源"/></label><label>待确认编号<select v-model="question" aria-label="按待确认编号筛选"><option value="">全部编号</option><option v-for="n in 31" :key="n" :value="'Q'+String(n).padStart(2,'0')">Q{{ String(n).padStart(2,'0') }}</option></select></label><label class="runtime-check"><input v-model="editableOnly" type="checkbox"/>只看可配置项</label><p>{{ catalogBusy?'读取中…':`显示 ${visible.length} / ${definitions.length} 项` }}</p><div class="runtime-keys"><button v-for="d in visible" :key="d.key" :class="{active:state.key===d.key}" :disabled="Boolean(state.busy)||workspace.unresolved()" @click="select(d.key)"><strong>{{d.key}}</strong><span>{{d.description}}</span><small>{{d.question_ids.join(' / ')||'合同明确'}} · {{d.editable?'可配置':'固定约束'}}</small></button></div></aside>
    <div class="runtime-workspace"><p v-if="!selected" class="panel runtime-empty">从左侧目录选择配置项</p><template v-else>
     <section class="panel"><div class="runtime-heading"><h2>{{selected.key}}</h2><button :disabled="Boolean(state.busy)||workspace.unresolved()" @click="refresh">刷新配置状态</button></div><p>{{selected.description}} · {{selected.question_ids.join(' / ')}}</p><div class="runtime-facts"><div><small>当前状态</small><strong>{{!selected.editable?'合同固定约束':state.current?statuses[state.current.status]:'读取中或未取得'}}</strong></div><div><small>最新发布版本</small><strong>{{state.current?.latest_version??'—'}}</strong></div><div><small>登记类型 / 单位</small><strong>{{selected.type}} / {{selected.unit??'无单位'}}</strong></div></div><p>登记作用域：{{selected.scope}}；本页发布作用域：当前租户。{{selected.allowed_range}}</p><ApiErrorNotice :error="state.error"/><p v-if="selected.editable" class="runtime-consumer-status"><strong>{{runtimeConsumer(selected.key).title}}</strong><br/>{{runtimeConsumer(selected.key).detail}}<router-link v-if="runtimeConsumer(selected.key).path&&runtimeConsumer(selected.key).capability&&can(runtimeConsumer(selected.key).capability!)" :to="runtimeConsumer(selected.key).path!">{{runtimeConsumer(selected.key).action}}</router-link></p><h3>当前有效值（配置记录）</h3><p v-if="state.current">读取时间：{{displayTime(state.current.observed_at)}}。定时生效和到期状态以重新读取为准。</p><pre>{{JSON.stringify(selected.editable?state.current?.effective_value??null:selected.registered_value,null,2)}}</pre><p v-if="state.current?.selected_release">正在解析发布 v{{state.current.selected_release.version}} · 生效 {{displayTime(state.current.selected_release.effective_at)}} · 到期 {{state.current.selected_release.expires_at?displayTime(state.current.selected_release.expires_at):'长期有效（不设到期）'}}</p><details><summary>查看配置校验结构</summary><pre>{{JSON.stringify(selected.schema,null,2)}}</pre></details></section>
     <section v-if="selected.editable" class="panel"><div class="runtime-heading"><h2>发布准备</h2><button v-if="selectedRegistry" :disabled="workspace.unresolved()||Boolean(state.busy)" @click="revisionsOpen=true">管理提案与内部审批</button></div><ApiErrorNotice :error="revisionError" @retry="readProposals(state.key)"/><p class="runtime-flow">保存提案 → 另一名管理员审核 → 在此发布</p><button :disabled="!writable||Boolean(state.busy)||workspace.unresolved()||confirming" @click="prepare">准备本次发布</button><p v-if="prepared">本次基于发布版本 {{prepared.version}}；刷新不会自动更换此版本。版本变化后需重新准备。</p><p v-else>先点击“准备本次发布”绑定当前版本，再填写操作。</p><fieldset :disabled="locked"><label>选择已审核提案<select v-model="selectedRevision" aria-label="选择已审核提案"><option value="">请选择已审批通过的提案版本</option><option v-for="r in approved" :key="r.id" :value="r.id">{{r.id}} · 提案 v{{r.version}}</option></select></label><p v-if="!approved.length">尚无已审核提案，可通过“管理提案与内部审批”完成准备。</p><template v-if="candidate"><pre>{{JSON.stringify(candidate.proposed_value,null,2)}}</pre><button @click="validateCandidate">{{validating?'校验中…':'校验所选提案'}}</button><span v-if="validated" role="status">已通过当前配置定义校验</span></template><div v-if="chosenRollback" class="runtime-warning">回滚目标：发布 v{{chosenRollback.version}}。将复制其值保存为新版本，历史不会删除。</div><label>生效方式<select v-model="activation" aria-label="配置生效方式"><option value="IMMEDIATE">发布事务完成时立即生效</option><option value="SCHEDULED">按指定 UTC 时间定时生效</option></select></label><label v-if="activation==='SCHEDULED'">生效UTC时间<input v-model="effectiveAt" aria-label="配置生效UTC时间" placeholder="例如2026-10-15T08:00:00Z"/></label><label>到期UTC时间（留空表示不设到期）<input v-model="expiresAt" aria-label="配置到期UTC时间"/></label><label>本次操作原因<textarea v-model="reason" maxlength="500" aria-label="配置发布原因" rows="3"/></label><label class="runtime-check"><input v-model="ack" type="checkbox" aria-label="确认当前测试租户发布"/>我确认在当前测试租户应用所选配置值（生产环境以客户正式签署结果为准）。</label><div class="runtime-actions"><button :disabled="!ack||!candidate||!validated" @click="publish('PUBLISH')">发布所选提案</button><button :disabled="!ack||!chosenRollback" @click="publish('ROLLBACK')">按历史值发布回滚版本</button><button :disabled="!ack||!state.current" @click="publish('DISABLE')">禁用此配置</button></div></fieldset><p v-if="validation" role="alert" class="runtime-warning">{{validation}}</p><div v-if="state.attempt" class="runtime-attempt"><p>本次请求：{{state.attempt.state==='accepted'?'发布回执已确认':state.attempt.state==='rejected'?'请求已明确拒绝':'结果尚未确认，不能另发新请求'}}</p><button v-if="state.attempt.state==='uncertain'" :disabled="Boolean(state.busy)" @click="retry">重试提交</button><button v-else :disabled="Boolean(state.busy)" @click="newCommand">准备下一次变更</button><p v-if="state.receipt">回执：发布 v{{state.receipt.version}} · {{state.receipt.id}}；当前有效值以独立回读为准。</p></div></section>
     <section class="panel"><h2>发布历史记录</h2><p v-if="!state.history.length">暂无发布记录</p><article v-for="r in state.history" :key="r.id" class="runtime-history-row"><div class="runtime-heading"><strong>v{{r.version}} · {{r.action}}</strong><button v-if="writable&&r.action!=='DISABLE'" :disabled="locked" @click="prepareRollback(r)">选择此版本回滚</button></div><p>{{r.reason}}</p><p>发布 {{displayTime(r.published_at)}} · 生效 {{displayTime(r.effective_at)}} · {{r.expires_at?'到期 '+displayTime(r.expires_at):'不设到期'}}</p><details><summary>查看保存值与来源</summary><pre>{{JSON.stringify(r.value,null,2)}}</pre><p>提案：{{r.revision_id??'禁用操作'}} · 定义摘要：{{r.definition_hash}}</p></details></article><div class="runtime-actions"><button :disabled="Boolean(state.busy)||workspace.unresolved()" @click="workspace.load()">最新历史</button><button :disabled="Boolean(state.busy)||!state.more||workspace.unresolved()" @click="workspace.load(state.key,state.history.at(-1)!.version)">更早的历史</button></div></section>
    </template></div>
   </div>
  </template>
  <ConfigurationRevisions v-model="revisionsOpen" :configuration="selectedRegistry" @changed="changed"/>
 </section>
</template>
<style scoped>
.runtime-layout{display:grid;grid-template-columns:300px minmax(0,1fr);gap:16px;margin-top:18px;align-items:start}.runtime-config-page .panel{padding:20px;background:white;border:1px solid #dfe7f0;border-radius:7px;min-width:0;margin-bottom:16px}.runtime-config-page h2{font-size:17px;margin:0 0 14px}.runtime-config-page h3{font-size:14px}.runtime-config-page p{color:#53677e;font-size:13px;line-height:1.7;overflow-wrap:anywhere}.runtime-config-page label{display:grid;gap:7px;margin:12px 0;font-size:13px}.runtime-config-page input:not([type=checkbox]),.runtime-config-page select,.runtime-config-page textarea{padding:9px 10px;min-height:44px;width:100%;max-width:100%;box-sizing:border-box;border:1px solid #bdccde;border-radius:5px;background:white;color:#263f60;font:inherit}.runtime-config-page button{min-height:44px;padding:8px 12px;border:1px solid #b9cbe1;background:white;color:#245e9f;border-radius:5px;cursor:pointer;overflow-wrap:anywhere}.runtime-config-page button:disabled{opacity:.55;cursor:default}.runtime-config-page .runtime-check{display:flex;align-items:center;gap:8px;line-height:1.7}.runtime-check input{width:18px;height:18px;flex-shrink:0}.runtime-keys{max-height:70vh;overflow:auto;display:grid;gap:6px}.runtime-keys button{text-align:left}.runtime-keys strong,.runtime-keys span,.runtime-keys small{display:block;margin:4px 0;overflow-wrap:anywhere}.runtime-keys strong{font-size:12px}.runtime-keys span,.runtime-keys small{font-size:11px;color:#5b7089}.runtime-keys .active{background:#eef5ff;border-color:#286fc4}.runtime-heading,.runtime-actions{display:flex;justify-content:space-between;align-items:center;gap:10px;flex-wrap:wrap}.runtime-actions{justify-content:flex-start;margin-top:14px}.runtime-facts{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px}.runtime-facts>div{background:#f5f8fc;padding:12px}.runtime-facts small,.runtime-facts strong{display:block;overflow-wrap:anywhere;margin:4px 0}.runtime-facts small{color:#63758c}.runtime-config-page pre{background:#f6f8fb;border-radius:5px;padding:12px;font-size:12px;white-space:pre-wrap;overflow-wrap:anywhere;max-height:320px;overflow:auto}.runtime-config-page fieldset{border:0;padding:0;min-width:0}.runtime-warning,.runtime-attempt{padding:12px;background:#fff5e5;border:1px solid #e8ce9b;border-radius:5px;font-size:13px;line-height:1.7}.runtime-history-row{padding:16px 0;border-bottom:1px solid #e0e8f1}.runtime-config-page details{margin:14px 0}@media(max-width:1000px){.runtime-layout{grid-template-columns:240px minmax(0,1fr)}}@media(max-width:760px){.runtime-layout{grid-template-columns:1fr}.runtime-keys{max-height:260px}.runtime-config-page .panel{padding:14px}.runtime-facts{grid-template-columns:1fr}.runtime-config-page button{min-height:44px}.runtime-actions>button{width:100%}}
.runtime-config-page :focus-visible{outline:3px solid #176bb5;outline-offset:3px}.runtime-check{min-height:44px}
.runtime-empty{display:flex;align-items:center;justify-content:center;min-height:220px;color:#6a7a8e;border-style:dashed!important}.runtime-flow{font-size:13px;color:#526176}
</style>
